        ''--%s\r\n''
        ''Content-Disposition: form-data; name="PHP_SESSION_UPLOAD_PROGRESS"\r\n\r\nx\r\n''
        ''--%s\r\n''
        ''Content-Disposition: form-data; name="f"; filename="%s"\r\n''
        "\r\nZ\r\n"
