INSERT INTO poc (id,code,title,kind,category,cve,component,versions,severity,language,source,source_url,description,usage,content,path,verified,verified_note,hit_count,used_on,engagement_id,engagement_name,asset_target,found_by_agent,tags,created_by,created_at,updated_at) VALUES (457,'php2shell-exploit-framework-cve-2026-109618-619-heap-oob-asl','PHP2Shell 通用利用框架（CVE-2026-109618/619）：session.upload_progress UAF → Heap OOB 泄露绕 ASLR → pDestructor=zif_system 预认证 RCE','script','rce','CVE-2026-109618,CVE-2026-109619','PHP 8.x（mod_php / php-fpm）/ session.upload_progress','PHP < 8.5.12 / < 8.4.27 / < 8.3.36 / < 8.2.35；8.1/8.0/7.x 全部 EOL','critical','markdown','web','https://github.com/JoasASantos/php2shell-exploit','【context 打法，未实测真实目标】第三方复现框架（Joas A Santos / @c0d3cr4zy，MIT）。把 CVE-2026-109618/619（PHP session.upload_progress 处理中的 UAF）做成一条四段纯 HTTP、无凭据、无 Cookie 的完整链：A1 END-cleanup send_cookie 时 OOM 造出悬垂 PS(id)/PS(mod_data) → B1 用 stale session id 做 Set-Cookie 越界读（约 800KB 堆泄露，拿到 libphp base + chunk base，绕过 ASLR）→ A2 cheap-OOM 造出悬垂 PS(http_session_vars) → B2 fake zend_reference spray 覆盖成伪 zend_array，pDestructor 指向 zif_system，shutdown 时 zend_hash_destroy 调 system(cmd)。攻击面是 PHP 自身 multipart/session 处理，不是具体应用，任意 PHP 入口页都能当打点；Apache mod_php + prefork 时最稳。前提：PHP 落在受影响区间、session.upload_progress.enabled=On、且能拿到与该 build 完全一致的 zif_system / zval_ptr_dtor 偏移（错了直接段错误）。','【定位】context 打法/工具参考，不是已打通的弹药。适合“目标 PHP 版本落在受影响区间且 upload_progress 开启”时评估与复现，实战里排在直接命令执行/文件写入路线之后。

# 0) 取源码（已留解包副本：D:\ARTEX\data\sessions\conv-684\php2shell-exploit-main；提炼文档同名 .md）
git clone --depth 1 https://github.com/JoasASantos/php2shell-exploit.git && cd php2shell-exploit

# 1) 起本地靶场（官方 php:8.4.26-apache + php.ini-production，单 prefork worker，128M，端口 18110）
